export async function syntheticIndependent(){const base=await syntheticNegative(),h={id:INDEPENDENT_HOLDOUT,organization_id:base.run.organization_id,establishment_id:base.run.establishment_id,source_experiment_id:base.run.id,expected_count:32,selection_fingerprint:''},items:HoldoutItem[]=await Promise.all(base.items.map(async(i,n)=>({holdout_id:h.id,review_id:negativeUuid(80000+n),position:n+1,overall_rating:i.overall_rating,analysis_text:'Synthetic English review '+n+': The food was good but we waited too long.',analysis_text_sha256:await negativeHash('Synthetic English review '+n+': The food was good but we waited too long.'),analysis_language:'en',analysis_source:'original_en',selection_bucket:i.selection_bucket,google_detailed_ratings:null}))),refs:BlindReference[]=items.map((i,n)=>({holdout_id:h.id,review_id:i.review_id,analysis_text_sha256:i.analysis_text_sha256,rubric_version:'human-aligned-review-rubric-v1',model_source:'chatgpt_gpt_6',reference_kind:'blind_ai_reference_not_human_gold',annotation_protocol:'english_only_25_theme_blind_to_v11_v12_predictions',theme_choices:Object.fromEntries(THEME_KEYS.map(k=>[k,k==='presentation'&&n<11?'uncertain':k==='wait_time'?'negative':k==='food_quality'?'positive':'absent'])) as BlindReference['theme_choices'],overall_text_sentiment:'mixed',notes_fr:'',uncertain_notes_fr:'',requires_review:n<11,created_at:'2026-10-09'})),hashes=await sealedFingerprints(items,refs);h.selection_fingerprint=hashes.dataset;const seal:BlindSeal={holdout_id:h.id,sealed_at:'2026-10-09',reference_kind:refs[0].reference_kind,rubric_version:refs[0].rubric_version,model_source:refs[0].model_source,reference_records:32,labeled_theme_choices:800,uncertain_theme_choices:11,reference_fingerprint:hashes.reference,frozen_dataset_fingerprint:hashes.dataset},prepared=await prepareIndependent(h,items,refs,seal,base.items.map(i=>i.review_id),{input:.042,output:0}),run:IndependentRun={id:negativeUuid(81112),holdout_id:h.id,organization_id:h.organization_id,establishment_id:h.establishment_id,status:'completed',config:INDEPENDENT_CONFIG,prepared,created_at:'2026-10-09',started_at:'2026-10-09T01:00:00Z',completed_at:'2026-10-09T01:02:00Z',error_code:null},tasks:IndependentTask[]=items.flatMap((i,n)=>(['v11','v12'] as const).flatMap((model_version,j)=>[1,2,3].map(repeat=>{const response=negativeDecision(['wait_time']);response.themes.food_quality={choice:'positive',probabilities:{absent:0,positive:1,negative:0,both:0}};return {id:negativeUuid(90000+n*6+j*3+repeat),run_id:run.id,review_id:i.review_id,model_version,review_alias:'r'+i.position,question_set:run.config[model_version].question_set,analysis_text_sha256:i.analysis_text_sha256,repeat,status:'completed',response,served_model:'jev-fixture',input_tokens:100,output_tokens:10,request_count:1,retry_count:0,cost_usd:.0000042,duration_ms:100,error_code:null,usage_complete:true}})))
 return {h,items,refs,seal,prepared,run,tasks,trainingIds:base.items.map(i=>i.review_id)}
}
